#define contrast .9

mat2 rot(float a) {
    float c = cos(a);
    float s = sin(a);
    return mat2(c, -s, s, c);
}

vec2 hash(float n) {
    float x = fract(sin(n) * 43758.5453123);
    float y = fract(cos(n) * 96317.6432154);
    return vec2(x, y);
}

vec2 noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 a = hash(dot(i, vec2(1.0, 57.0)));
    vec2 b = hash(dot(i + vec2(1.0, 0.0), vec2(1.0, 57.0)));
    vec2 c = hash(dot(i + vec2(0.0, 1.0), vec2(1.0, 57.0)));
    vec2 d = hash(dot(i + vec2(1.0, 1.0), vec2(1.0, 57.0)));
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float wave(vec2 p, float t) {
    t = pow(t, 0.3);
    vec2 center = vec2(0., 0.);
    p += t * 0.2;
    float dist = length(p - center);
    float attenuation = step(length(p), t * 0.25);
    attenuation *= exp(-10.0 * t * length(p));
    float waveTime = smoothstep(1.0, 0.5, t);
    float wave = sin(100.0 * dist - 25.0 * t) * waveTime;
    wave *= attenuation;
    return wave;
}

float dr;
float map(vec3 p) {
    vec3 p3 = p;
    p.x = mod(p.x + iTime * 0.1, 2.) - 1.0;
    vec2 uv = p.xz;
    uv += (noise(uv * 50.0) - 0.5) * 0.01;
    float t = fract(iTime);
    float tf = floor(iTime);
    float c = 0.0;
    float d = 1000.0;
    for (float i = 0.; i < 15.; i++) {
        vec2 h = hash(i * 0.123) - 0.5;
        h*=1.3;
        c += wave(uv + h, fract(t + i * 0.2)) * 0.2;
        vec3 p2 = p + t * 0.2;
        p2.y = mod(p2.y * 0.2 + t + 0.4 + i * 0.2, 1.0) - 0.5;
        float dro = length(p2 + vec3(h.x, 0.0, h.y))+.002;
        d = min(d, dro);
    }
    dr = d;
    float t2 = iTime * 1.5;
    uv = p3.xz * 0.7;
    float h = 0.4;
    c += noise(uv * 5.0 + t2).x * 0.6 * h;
    c += noise(uv * 10.0 + t2).x * 0.4 * h;
    c += noise(uv * 20.0 + t2).x * 0.2 * h;
    return c;
}

float de(vec3 p) {
    float wat = p.y;
    float wav = map(p);
    wat -= wav * 0.1;
    float d = min(wat, dr);
    return d * 0.5;
}

float det = 0.01;

vec3 normal(vec3 p) {
    vec2 e = vec2(0.0, det);
    return normalize(vec3(de(p + e.yxx), de(p + e.xyx), de(p + e.xxy)) - de(p));
}

vec3 march(vec3 from, vec3 dir) {
    vec3 p = from, col = vec3(0.0);
    float d, td = 0.0, maxdist = 50.0;
    float g = 0.0;
    for (int i = 0; i < 200; i++) {
        d = de(p);
        p += d * dir;
        if (d < det || td > maxdist) break;
    }
    if (d < det) {
        vec3 n = normal(p);
        vec3 ldir = normalize(vec3(0.3, 1.0, -1.0));
        float dif = max(0., dot(-dir, n));
        vec3 ref = reflect(dir, ldir);
        float spe = max(0.0, dot(ref, n));
        spe = pow(spe, 50.0) * 0.65;
        col = vec3(spe + dif * 0.025);
        g += 0.1 / (0.1 + dr * 10.0);
    }
    return col + g * 0.05;
}

vec2 rand2(vec2 co) {
    return vec2(fract(sin(dot(co.xy, vec2(12.9898, 78.233))) * 43758.5453),
                fract(cos(dot(co.xy, vec2(4.898, 7.23))) * 23421.631));
}

vec2 uniformDisc(vec2 co) {
    vec2 r = rand2(co);
    return sqrt(r.y) * vec2(cos(r.x * 6.28), sin(r.x * 6.28));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - iResolution.xy * 0.5) / iResolution.y;
    uv += uniformDisc(uv + iTime) * (0.02 * (uv.y + 0.3) + .05*max(0.,2.-iTime));
    vec3 from = vec3(0.0, 1.0, -1.7);
    vec3 dir = normalize(vec3(uv, 2. + .5*asin(0.8 * sin(10.0 + iTime * 0.3))));
    dir.yz *= rot(0.5);
    vec3 col = march(from, dir);
    col *= vec3(0.9, 0.95, 1.0);
    col=pow(col,vec3(contrast));
    fragColor = vec4(col, 1.0);
}
